var day0 = time.Date(2026, 10, 26, 0, 0, 0, 0, time.UTC)

// steady builds 60 days before day0 alternating around a median, plus the
// given values on day0.
func steady(today map[string]float64) Series {
	base := map[string][2]float64{ // median, alternating offset
		RestingHR: {50, 1}, HRV: {60, 3}, Sleep: {27000, 900}, SleepScr: {80, 4}, BodyHigh: {90, 3}, Stress: {30, 2},
	}
	s := Series{}
	for m, b := range base {
		s[m] = map[time.Time]float64{}
		for i := 1; i <= 60; i++ {
			off := b[1]
			if i%2 == 0 {
				off = -off
			}
			s[m][day0.AddDate(0, 0, -i)] = b[0] + off
		}
	}
	for m, v := range today {
		if s[m] == nil {
			s[m] = map[time.Time]float64{}
		}
		s[m][day0] = v
	}
	return s
}

func fitnessWith(ratio, form float64) map[time.Time]analysis.FitnessDay {
	return map[time.Time]analysis.FitnessDay{
		day0.AddDate(0, 0, -1): {ACWR: ratio},
		day0:                   {Form: form, Fitness: 50},
	}
}

func TestNormalAndDeviation(t *testing.T) {
	s := steady(map[string]float64{RestingHR: 55})
	n, ok := NormalFor(s, RestingHR, day0, 60, 14)
	// Values 49/51 → median 50, MAD 1 → spread 1.4826.
	if !ok || n.Median != 50 || math.Abs(n.Spread-1.4826) > 1e-9 || n.N != 60 {
		t.Fatalf("normal %+v %v", n, ok)
	}
	if _, ok := NormalFor(s, RestingHR, day0, 10, 14); ok {
		t.Error("too few values")
	}
	// Resting HR uses the 3-day mean: (55 + 51 + 49) / 3 = 51.67 → slightly high.
	d, ok := DeviationOn(s, RestingHR, day0, 60, 14)
	if !ok || math.Abs(d.Value-155.0/3) > 1e-9 || d.Z >= 0 || d.Band() != 1 {
		t.Errorf("deviation %+v band %d", d, d.Band())
	}
	// Stable metric: the floor keeps the spread at 1 bpm minimum.
	flat := Series{RestingHR: {}}
	for i := 1; i <= 20; i++ {
		flat[RestingHR][day0.AddDate(0, 0, -i)] = 50
	}
	if n, _ := NormalFor(flat, RestingHR, day0, 60, 14); n.Spread != 1 {
		t.Errorf("floor %+v", n)
	}
	if FormatRange(RestingHR, 49, 51) != "49–51 bpm" || FormatRange(Sleep, 25200, 27900) != "7:00–7:45 h" || FormatRange(Stress, 27, 33) != "27–33" {
		t.Error("FormatRange")
	}
}

func TestReadinessClassesAndReasons(t *testing.T) {
	cfg := Defaults()
	good := steady(map[string]float64{RestingHR: 48, HRV: 66, HRVLow: 55, HRVHigh: 70, Sleep: 28800, SleepScr: 88, BodyHigh: 95, Stress: 25})
	r, ok := ComputeReadiness(good, fitnessWith(1.0, 0), day0, cfg)
	if !ok || r.Class != ClassReady || r.Score < cfg.ReadyAt || len(r.Factors) != 5 || r.Warning != "" {
		t.Fatalf("good %+v", r)
	}
	bad := steady(map[string]float64{RestingHR: 60, HRV: 40, HRVLow: 55, HRVHigh: 70, Sleep: 18000, SleepScr: 50, BodyHigh: 50, Stress: 50})
	r, ok = ComputeReadiness(bad, fitnessWith(1.6, -25), day0, cfg)
	if !ok || r.Class != ClassLimited || len(r.Reasons) != 2 {
		t.Fatalf("bad %+v", r)
	}
	if !strings.Contains(strings.Join(r.Reasons, "|"), "unter deiner Basis") && !strings.Contains(strings.Join(r.Reasons, "|"), "Schlaf 5:00 h") {
		t.Errorf("reasons %v", r.Reasons)
	}
	// Only one recovery factor → no statement.
	only := steady(map[string]float64{RestingHR: 50})
	delete(only, BodyHigh)
	delete(only, Stress)
	if _, ok := ComputeReadiness(only, nil, day0, cfg); ok {
		t.Error("one factor is not enough")
	}
	// Body Battery and stress count from yesterday, the last complete day.
	if r, _ := ComputeReadiness(good, nil, day0, cfg); !strings.Contains(strings.Join(r.Reasons, "|")+factorTexts(r), "(gestern)") {
		t.Errorf("body factor from yesterday: %+v", r.Factors)
	}
	// Without the load factor the weights are renormalized.
	if r, ok := ComputeReadiness(good, nil, day0, cfg); !ok || len(r.Factors) != 4 || r.Class != ClassReady {
		t.Errorf("without load %+v", r)
	}
}

func TestWarning(t *testing.T) {
	cfg := Defaults()
	s := steady(nil)
	for i := range 3 {
		s[RestingHR][day0.AddDate(0, 0, -i)] = 57
	}
	s[HRV][day0], s[HRVLow] = 45, map[time.Time]float64{day0: 55}
	s[HRVHigh] = map[time.Time]float64{day0: 70}
	r, ok := ComputeReadiness(s, fitnessWith(1.0, 0), day0, cfg)
	if !ok || !strings.Contains(r.Warning, "seit 3 Tagen") || !strings.Contains(r.Warning, "HRV unter deiner Basis") {
		t.Fatalf("warning %q", r.Warning)
	}
	if rec := Recommend(&r, fitnessWith(1.0, 0), nil, day0, 100, cfg); rec.Kind != RecRest {
		t.Errorf("warning → rest day, got %s", rec.Kind)
	}
	// Two elevated days are not enough.
	s[RestingHR][day0.AddDate(0, 0, -2)] = 50
	if r, _ := ComputeReadiness(s, nil, day0, cfg); r.Warning != "" {
		t.Errorf("no warning expected: %q", r.Warning)
	}
}

func TestRecommendRules(t *testing.T) {
	cfg := Defaults()
	ready := &Readiness{Class: ClassReady}
	normal := &Readiness{Class: ClassNormal}
	limited := &Readiness{Class: ClassLimited}
	loads := map[time.Time]float64{}
	for _, c := range []struct {
		name        string
		r           *Readiness
		ratio, form float64
		hard        bool
		want        string
	}{
		{"limited and tired", limited, 1.0, -25, false, RecRest},
		{"limited and high ratio", limited, 1.6, 0, false, RecRest},
		{"limited", limited, 1.0, 0, false, RecEasy},
		{"very tired", ready, 1.0, -35, false, RecEasy},
		{"ratio high", ready, 1.4, 0, false, RecEasy},
		{"three hard days", ready, 1.0, 0, true, RecEasy},
		{"ready", ready, 1.1, -5, false, RecHard},
		{"ready but tired", ready, 1.0, -15, false, RecModerate},
		{"normal", normal, 1.0, 0, false, RecModerate},
		{"no health data", nil, 1.0, 0, false, RecModerate},
	} {
		for i := 1; i <= 3; i++ {
			loads[day0.AddDate(0, 0, -i)] = 50
			if c.hard {
				loads[day0.AddDate(0, 0, -i)] = 150
			}
		}
		rec := Recommend(c.r, fitnessWith(c.ratio, c.form), loads, day0, 100, cfg)
		if rec.Kind != c.want {
			t.Errorf("%s: %s, want %s (%v)", c.name, rec.Kind, c.want, rec.Reasons)
		}
		if c.r == nil && !strings.Contains(strings.Join(rec.Reasons, " "), "ohne aktuelle Gesundheitsdaten") {
			t.Errorf("missing data note: %v", rec.Reasons)
		}
	}
	// Hints on the development of fitness.
	fit := map[time.Time]analysis.FitnessDay{day0: {Fitness: 60}, day0.AddDate(0, 0, -7): {Fitness: 50}, day0.AddDate(0, 0, -28): {Fitness: 80}}
	if rec := Recommend(ready, fit, nil, day0, 0, cfg); len(rec.Hints) != 2 {
		t.Errorf("hints %v", rec.Hints)
	}
}

