func TestDistribution(t *testing.T) {
	d := AssessDistribution(map[int]float64{1: 10, 2: 6, 3: 2, 4: 1.5, 5: 0.5}, []float64{50, 0, 80, 0, 60, 120, 0}, 16, 4)
	if math.Abs(d.Easy-0.8) > 1e-9 || !strings.Contains(d.Statements[0], "Polarisierte") || d.Monotony > 2 || d.ActiveDaysPerWeek != 4 {
		t.Errorf("polarized %+v", d)
	}
	d = AssessDistribution(map[int]float64{1: 2, 2: 3, 3: 4, 4: 0.1}, []float64{60, 62, 58, 61, 59, 60, 60}, 4, 4)
	text := strings.Join(d.Statements, " ")
	if !strings.Contains(text, "Viel mittlere Intensität") || !strings.Contains(text, "Kaum intensive") ||
		!strings.Contains(text, "gleichförmige") || !strings.Contains(text, "1,0 aktive Tage") {
		t.Errorf("threshold-heavy %+v", d.Statements)
	}
}

func TestQuantile75(t *testing.T) {
	loads := map[time.Time]float64{}
	for i := range 9 {
		loads[day0.AddDate(0, 0, -i)] = float64(i * 10) // 0 is ignored → 10…80
	}
	if q := Quantile75(loads); q != 60 {
		t.Errorf("q75 %v", q)
	}
}

func factorTexts(r Readiness) string {
	var b strings.Builder
	for _, f := range r.Factors {
		b.WriteString(f.Text + "|")
	}
	return b.String()
}

